package com.blitterstudio.amiberry.data.model

object EmulatorSettingsConstraints {

	/**
	 * The CPU, chipset and memory sizes come out as the emulator resolves
	 * them when it loads the configuration ([schema]'s resolution tables,
	 * generated by the emulator's own checks); the rest are the launcher's
	 * rules for what it offers on Android. Without a schema they are left as
	 * requested.
	 */
	fun apply(
		settings: EmulatorSettings,
		hasTouchScreen: Boolean,
		schema: SettingsSchema? = SettingsSchema.current
	): EmulatorSettings {
		var result = resolveCpuAndChipset(settings, schema?.resolutions)
		result = resolveMemory(result, schema?.memoryResolutions)

		if (result.gfxWidth <= 0 || result.gfxHeight <= 0) {
			result = result.copy(gfxWidth = DEFAULT_GFX_WIDTH, gfxHeight = DEFAULT_GFX_HEIGHT)
		}

		result = result.copy(
			soundOutput = normalizeSoundOutput(result.soundOutput, result.isCycleExact),
			soundFreq = if (result.soundFreq > 0) result.soundFreq else DEFAULT_SOUND_FREQUENCY,
			// 0 is the emulator's "Min"; off-list sizes are valid native values too
			soundBuffer = if (result.soundBuffer >= 0) result.soundBuffer else DEFAULT_SOUND_BUFFER,
			soundChannels = normalizeSoundChannels(result.soundChannels)
		)

		if (result.scalingMethod == SCALING_METHOD_INTEGER && result.gfxAutoresolution != AUTORESOLUTION_ALWAYS) {
			result = result.copy(gfxAutoresolution = AUTORESOLUTION_ALWAYS)
		} else if (result.gfxAutoresolution == AUTORESOLUTION_ALWAYS && result.scalingMethod != SCALING_METHOD_INTEGER) {
			result = result.copy(scalingMethod = SCALING_METHOD_INTEGER)
		}

		val floppy0 = normalizeFloppyDrive(result.floppy0, result.floppy0Type)
		val floppy1 = normalizeFloppyDrive(result.floppy1, result.floppy1Type)
		val floppy2 = normalizeFloppyDrive(result.floppy2, result.floppy2Type)
		val floppy3 = normalizeFloppyDrive(result.floppy3, result.floppy3Type)
		result = result.copy(
			floppy0 = floppy0.path,
			floppy0Type = floppy0.driveType,
			floppy1 = floppy1.path,
			floppy1Type = floppy1.driveType,
			floppy2 = floppy2.path,
			floppy2Type = floppy2.driveType,
			floppy3 = floppy3.path,
			floppy3Type = floppy3.driveType
		)

		val normalizedJoyport0 = normalizeJoyport0(result.joyport0)
		if (normalizedJoyport0 != result.joyport0) {
			result = result.copy(joyport0 = normalizedJoyport0)
		}

		if (!hasTouchScreen && (result.joyport1 == "onscreen_joy" || result.onScreenJoystick)) {
			result = result.copy(joyport1 = "joy1", onScreenJoystick = false)
		} else if (result.onScreenJoystick) {
			result = result.copy(joyport1 = "onscreen_joy")
		} else if (result.joyport1 == "onscreen_joy") {
			result = result.copy(joyport1 = "joy1")
		}

		val normalizedJoyport1 = normalizeJoyport1(result.joyport1)
		if (normalizedJoyport1 != result.joyport1) {
			result = result.copy(joyport1 = normalizedJoyport1, onScreenJoystick = false)
		}

		// The analog mouse map feeds the Amiga mouse on port 0 (setmousestate
		// on an unassigned mouse is a no-op), so it only works with a
		// controller on port 1 and the system mouse kept on port 0. Port 0
		// can hold either a controller or the mouse, never both.
		if (result.joyport0MouseMap) {
			result = result.copy(joyport0MouseMap = false)
		}
		if (result.joyport1MouseMap && !(result.joyport1 in JOYSTICK_DEVICES && result.joyport0 == "mouse")) {
			result = result.copy(joyport1MouseMap = false)
		}

		// Off-slider speeds (hotkeys, hand-edited configs) stay; only invalid ones reset
		if (result.analogMouseSpeed <= 0) {
			result = result.copy(analogMouseSpeed = DEFAULT_ANALOG_MOUSE_SPEED)
		}

		return result
	}

	/**
	 * Looks the request up in the resolution table, which says what the
	 * emulator runs with after loading it. The table's chipset input is the
	 * family (ocs, ecs, aga); a chipset variant the family keeps stays as
	 * chosen. JIT and Z3 sizes are looked up as on or off and keep the size
	 * chosen while the emulator keeps them on. The table knows cycle-exact as
	 * on or off; the core's checks treat both modes alike (fixup_cpu in
	 * src/main.cpp), so a DMA/memory mode it keeps stays as chosen.
	 */
	private fun chipsetFamily(chipset: String) = when (chipset) {
		"aga" -> "aga"
		"ocs", "a1000", "a1000_noehb" -> "ocs"
		else -> "ecs"
	}

	private fun resolveCpuAndChipset(s: EmulatorSettings, resolutions: Resolutions?): EmulatorSettings {
		resolutions ?: return s
		val family = chipsetFamily(s.chipset)
		val resolved = resolutions.resolve(
			mapOf(
				"chipset" to family,
				"cpu_model" to s.cpuModel.toString(),
				"fpu_model" to s.fpuModel.toString(),
				"cpu_24bit_addressing" to s.address24Bit.toString(),
				"cycle_exact" to s.isCycleExact.toString(),
				"cachesize" to if (s.jitCacheSize > 0) "8192" else "0",
				"z3mem_size" to if (s.z3Ram > 0) "16" else "0",
				"cpu_speed" to s.cpuSpeed,
				"cpu_compatible" to s.cpuCompatible.toString(),
				"compfpu" to s.jitFpu.toString(),
				"immediate_blits" to s.immediateBlits.toString()
			)
		) ?: return s
		fun flag(id: String, current: Boolean) = resolved[id]?.let { it == "true" } ?: current
		return s.copy(
			chipset = resolved["chipset"]?.takeIf { it != family } ?: s.chipset,
			cpuModel = resolved["cpu_model"]?.toIntOrNull() ?: s.cpuModel,
			fpuModel = resolved["fpu_model"]?.toIntOrNull() ?: s.fpuModel,
			address24Bit = flag("cpu_24bit_addressing", s.address24Bit),
			cycleExact = if (resolved["cycle_exact"] == "false") "false" else s.cycleExact,
			cpuCompatible = flag("cpu_compatible", s.cpuCompatible),
			cpuSpeed = resolved["cpu_speed"]?.takeIf { it == "real" || it == "max" } ?: s.cpuSpeed,
			jitCacheSize = if (resolved["cachesize"] == "0") 0 else s.jitCacheSize,
			jitFpu = flag("compfpu", s.jitFpu),
			immediateBlits = flag("immediate_blits", s.immediateBlits),
			z3Ram = if (resolved["z3mem_size"] == "0") 0 else s.z3Ram
		)
	}

	/**
	 * Chip, slow and Z2 fast RAM sizes as the emulator resolves them for the
	 * (already resolved) chipset, addressing and JIT: for example 1.5 MB chip
	 * RAM is 2 MB with the JIT. Conflicts with a preset's own hardware (a
	 * Gayle and 1.8 MB slow RAM) are left to the emulator.
	 */
	private fun resolveMemory(s: EmulatorSettings, resolutions: Resolutions?): EmulatorSettings {
		resolutions ?: return s
		val resolved = resolutions.resolve(
			mapOf(
				"chipset" to chipsetFamily(s.chipset),
				"cpu_24bit_addressing" to s.address24Bit.toString(),
				"cachesize" to if (s.jitCacheSize > 0) "8192" else "0",
				"chipmem_size" to s.chipRam.toString(),
				"bogomem_size" to s.slowRam.toString(),
				"fastmem_size" to s.fastRam.toString()
			)
		) ?: return s
		return s.copy(
			chipRam = resolved["chipmem_size"]?.toIntOrNull() ?: s.chipRam,
			slowRam = resolved["bogomem_size"]?.toIntOrNull() ?: s.slowRam,
			fastRam = resolved["fastmem_size"]?.toIntOrNull() ?: s.fastRam
		)
	}

	/**
	 * A sound mode the emulator has (the schema's sound_output choices), with
	 * the old "good" and "best" spellings read as it reads them. Cycle-exact
	 * timing needs Paula emulation, so the core raises a disabled sound
	 * setting to "interrupts" (fixup_cpu in src/main.cpp).
	 */
	private fun normalizeSoundOutput(soundOutput: String, cycleExact: Boolean): String = when {
		soundOutput == "none" && cycleExact -> "interrupts"
		soundOutput in EmulatorSettings.soundOutputOptions.map { it.first } -> soundOutput
		soundOutput == "good" -> "normal"
		soundOutput == "best" -> "exact"
		else -> DEFAULT_SOUND_OUTPUT
	}

	private fun normalizeSoundChannels(soundChannels: String): String =
		if (soundChannels in NATIVE_SOUND_CHANNELS) soundChannels else DEFAULT_SOUND_CHANNELS

	/**
	 * A disabled drive holds no disk. Every drive type the emulator has (the
	 * schema's floppyNtype choices) is kept; an unknown one becomes a 3.5" DD
	 * drive, or a disabled one when it holds no disk. Without a schema the
	 * type is kept.
	 */
	private fun normalizeFloppyDrive(path: String, driveType: Int): NormalizedFloppyDrive {
		val validTypes = EmulatorSettings.floppyTypeOptions.map { it.first }
		return when {
			driveType == FLOPPY_TYPE_DISABLED -> NormalizedFloppyDrive(path = "", driveType = FLOPPY_TYPE_DISABLED)
			validTypes.isEmpty() || driveType in validTypes -> NormalizedFloppyDrive(path = path, driveType = driveType)
			path.isBlank() -> NormalizedFloppyDrive(path = "", driveType = FLOPPY_TYPE_DISABLED)
			else -> NormalizedFloppyDrive(path = path, driveType = FLOPPY_TYPE_DD)
		}
	}

	private fun normalizeJoyport0(joyport0: String): String =
		if (joyport0 in ANDROID_PORT_INPUT_DEVICES) joyport0 else DEFAULT_JOYPORT0

	private fun normalizeJoyport1(joyport1: String): String =
		if (joyport1 in ANDROID_PORT_INPUT_DEVICES || joyport1 == "onscreen_joy") joyport1 else DEFAULT_JOYPORT1

	private const val DEFAULT_GFX_WIDTH = 720
	private const val DEFAULT_GFX_HEIGHT = 568
	private const val DEFAULT_SOUND_OUTPUT = "exact"
	// The Android build's defaults (settings_sound.cpp and options.h under
	// __ANDROID__): Android mixes at 48 kHz, so 44.1 kHz forces resampling and
	// loses AAudio's low-latency path, and it needs more queued audio to ride
	// out scheduling stalls. The bundled schema comes from a desktop build and
	// carries the desktop defaults (44100 Hz, 3072), so they are not read from it.
	const val DEFAULT_SOUND_FREQUENCY = 48000
	const val DEFAULT_SOUND_BUFFER = 8192
	private const val DEFAULT_SOUND_CHANNELS = "stereo"
	private const val SCALING_METHOD_INTEGER = 2
	private const val AUTORESOLUTION_ALWAYS = 1
	private const val DEFAULT_JOYPORT0 = "mouse"
	private const val DEFAULT_JOYPORT1 = "joy1"
	private const val FLOPPY_TYPE_DISABLED = -1
	private const val FLOPPY_TYPE_DD = 0
	private val JOYSTICK_DEVICES = setOf("joy0", "joy1")
	private val ANDROID_PORT_INPUT_DEVICES = setOf(
		"none",
		"mouse",
		"joy0",
		"joy1",
		"kbd1",
		"kbd2",
		"kbd3",
		"kbd9"
	)
	private val NATIVE_SOUND_CHANNELS: Set<String>
		get() = EmulatorSettings.soundChannelOptions.map { it.first }.toSet()
	/** The emulator's default pointer speed for the left stick as mouse. */
	val DEFAULT_ANALOG_MOUSE_SPEED: Int
		get() = EmulatorSettings.schemaInt("input.joymouse_speed_analog", 25)

	private data class NormalizedFloppyDrive(
		val path: String,
		val driveType: Int
	)
}
